import { ApiProperty, ApiPropertyOptional, PartialType } from '@nestjs/swagger';
import { Transform } from 'class-transformer';
import { IsBoolean, IsOptional, IsString, Length, Matches } from 'class-validator';

/** Collapses runs of whitespace so "Table  01" and "Table 01" are one name. */
const normaliseName = ({ value }: { value: unknown }) =>
  typeof value === 'string' ? value.trim().replace(/\s+/g, ' ') : value;

/**
 * No `restaurantId` and no token: the tenant comes from the access token and the
 * QR token is always generated by the server.
 */
export class CreateTableDto {
  @ApiProperty({ example: 'Table 01', minLength: 1, maxLength: 60 })
  @Transform(normaliseName)
  @IsString()
  @Length(1, 60)
  // Printable text only - the name is drawn onto printed QR cards.
  @Matches(/^[^\p{Cc}\p{Cf}]+$/u, { message: 'name must not contain control characters' })
  name: string;

  @ApiPropertyOptional({ example: true, default: true })
  @IsOptional()
  @IsBoolean()
  isActive?: boolean;
}

export class UpdateTableDto extends PartialType(CreateTableDto) {}
